return [
  {
    json: {
      event_id: "evt_demo_001",

      timestamp: new Date().toISOString(),

      source: "sales",

      event_type: "revenue_drop",

      severity: "high",

      entity: {
        type: "business",
        id: "demo_company"
      },

      data: {
        current_revenue: 84000,
        previous_revenue: 121000,
        percentage_change: -30.58
      },

      context: {
        period: "daily",
        region: "India"
      },

      metadata: {
        environment: "development",
        generated_by: "aegis-event-ingestion"
      }
    }
  }
];

const requiredFields = [
  "event_id",
  "timestamp",
  "source",
  "event_type",
  "severity",
  "data"
];

const allowedSources = [
  "sales",
  "support",
  "finance",
  "marketing",
  "github",
  "email",
  "crm",
  "system",
  "api"
];

const allowedSeverities = [
  "info",
  "low",
  "medium",
  "high",
  "critical"
];

const events = $input.all();

return events.map((item) => {
  const event = item.json;

  const errors = [];

  // Check required fields
  for (const field of requiredFields) {
    if (
      event[field] === undefined ||
      event[field] === null ||
      event[field] === ""
    ) {
      errors.push(`Missing required field: ${field}`);
    }
  }

  // Validate source
  if (
    event.source &&
    !allowedSources.includes(event.source)
  ) {
    errors.push(`Invalid source: ${event.source}`);
  }

  // Validate severity
  if (
    event.severity &&
    !allowedSeverities.includes(event.severity)
  ) {
    errors.push(`Invalid severity: ${event.severity}`);
  }

  // Validate data
  if (
    event.data !== undefined &&
    (typeof event.data !== "object" || Array.isArray(event.data))
  ) {
    errors.push("Field 'data' must be an object");
  }

  const valid = errors.length === 0;

  return {
    json: {
      ...event,

      validation: {
        valid,
        errors,
        validated_at: new Date().toISOString()
      }
    }
  };
});
